RSpec.describe Timekeeping::Handoff::TimekeepingStore do
  # "Admission: fence and admit through `Timekeeping::Admission.fence!` and `Timekeeping::Admission.admit!`, from the admission-fence work this depends on."
  it "sends fence and admit to Timekeeping with the service bearer and raises Store::Error on a refused fence" do
    store = described_class.new(base_url: "http://timekeeping.test", token: "svc-token")
    admit_url = "http://timekeeping.test/internal/v1/handoff/admission/admit"
    fence_url = "http://timekeeping.test/internal/v1/handoff/admission/fence"
    stub_request(:post, admit_url).to_return(status: 200, body: { generation: 2 }.to_json)
    stub_request(:post, fence_url).to_return(status: 503, body: { reason: "fence_timeout" }.to_json)

    store.admit(generation: 2)

    expect(WebMock).to have_requested(:post, admit_url)
      .with(headers: { "Authorization" => "Bearer svc-token" }, body: hash_including("generation" => 2))
    expect { store.fence_admission }.to raise_error(Timekeeping::Handoff::Store::Error)
    expect(WebMock).to have_requested(:post, fence_url).with(headers: { "Authorization" => "Bearer svc-token" })
  end
end

